import { useRef, useEffect, useState } from "react";
import { BrowserMultiFormatReader } from "@zxing/browser";
import { Result } from "@zxing/library";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { X, Camera, ScanLine } from "lucide-react";

interface BarcodeScannerProps {
  onScan: (barcode: string) => void;
  onClose: () => void;
  isOpen: boolean;
}

export default function BarcodeScanner({ onScan, onClose, isOpen }: BarcodeScannerProps) {
  const videoRef = useRef<HTMLVideoElement>(null);
  const readerRef = useRef<BrowserMultiFormatReader | null>(null);
  const [isScanning, setIsScanning] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const lastScannedBarcodeRef = useRef<string | null>(null);
  const isProcessingRef = useRef<boolean>(false);

  useEffect(() => {
    if (isOpen && !readerRef.current) {
      readerRef.current = new BrowserMultiFormatReader();
    }

    if (isOpen && videoRef.current && readerRef.current && !isScanning) {
      startScanning();
    }

    return () => {
      stopScanning();
    };
  }, [isOpen]);

  const startScanning = async () => {
    if (!videoRef.current || !readerRef.current) return;

    try {
      setIsScanning(true);
      setError(null);

      const videoInputDevices = await BrowserMultiFormatReader.listVideoInputDevices();

      if (videoInputDevices.length === 0) {
        throw new Error("No camera devices found");
      }

      // Prefer back camera if available
      const selectedDevice = videoInputDevices.find((device: MediaDeviceInfo) => 
        device.label.toLowerCase().includes('back') || 
        device.label.toLowerCase().includes('rear')
      ) || videoInputDevices[0];

      await readerRef.current.decodeFromVideoDevice(
        selectedDevice.deviceId,
        videoRef.current,
        (result?: Result, err?: Error) => {
          if (result && !isProcessingRef.current) {
            const barcode = result.getText();

            // Prevent duplicate scans of the same barcode
            if (lastScannedBarcodeRef.current === barcode) {
              return;
            }

            console.log("Barcode detected:", barcode);
            lastScannedBarcodeRef.current = barcode;
            isProcessingRef.current = true;

            setIsScanning(false);
            stopScanning();
            onScan(barcode);
          }
          if (err && !err.message.includes('No MultiFormat Readers were able to detect the code')) {
            console.log("Scanning error:", err);
          }
        }
      );
    } catch (err) {
      console.error("Scanner error:", err);
      setError(err instanceof Error ? err.message : "Failed to start camera");
      setIsScanning(false);
    }
  };

  const stopScanning = () => {
    if (readerRef.current) {
      try {
        // Stop the video stream
        const video = videoRef.current;
        if (video && video.srcObject) {
          const stream = video.srcObject as MediaStream;
          stream.getTracks().forEach(track => track.stop());
          video.srcObject = null;
        }
        // Note: BrowserMultiFormatReader doesn't have a reset method
        // Resources are cleaned up when video stream is stopped
      } catch (e) {
        // Ignore errors when stopping
      }
    }
    setIsScanning(false);
  };

  const handleClose = () => {
    stopScanning();
    // Reset scanning state when closing
    lastScannedBarcodeRef.current = null;
    isProcessingRef.current = false;
    onClose();
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black/90 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <Card className="w-full max-w-lg bg-black/95 border-red-600/50 shadow-2xl">
        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-4 border-b border-red-800/30">
          <CardTitle className="flex items-center gap-3 text-white">
            <div className="p-2 bg-gradient-to-r from-red-600 to-red-800 rounded-lg shadow-lg">
              <ScanLine className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold">Professional Scanner</span>
          </CardTitle>
          <Button 
            variant="ghost" 
            size="sm" 
            onClick={handleClose}
            data-testid="button-close-scanner"
            className="text-gray-300 hover:text-white hover:bg-red-600/20 border border-red-800/30 hover:border-red-600"
          >
            <X className="w-4 h-4" />
          </Button>
        </CardHeader>
        <CardContent className="space-y-6 p-6">
          {error ? (
            <div className="text-center space-y-6">
              <div className="bg-red-950/50 border border-red-800/50 rounded-lg p-6">
                <div className="w-16 h-16 bg-red-900/50 rounded-full flex items-center justify-center mx-auto mb-4">
                  <Camera className="w-8 h-8 text-red-400" />
                </div>
                <p className="text-red-300 font-medium">{error}</p>
                <p className="text-gray-400 text-sm mt-2">Please check camera permissions and try again</p>
              </div>
              <Button 
                onClick={startScanning} 
                className="bg-gradient-to-r from-red-600 to-red-700 hover:from-red-700 hover:to-red-800 text-white font-semibold px-6 py-3 rounded-lg shadow-lg transform hover:scale-105 transition-all duration-200"
                data-testid="button-retry-scanner"
              >
                <Camera className="w-4 h-4 mr-2" />
                Retry Scanner
              </Button>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="relative bg-black rounded-xl overflow-hidden border-2 border-red-600/30 shadow-2xl" style={{ aspectRatio: '4/3' }}>
                <video
                  ref={videoRef}
                  className="w-full h-full object-cover"
                  playsInline
                  data-testid="video-scanner"
                />
                {isScanning && (
                  <div className="absolute inset-0 flex items-center justify-center">
                    <div className="relative">
                      {/* Scanning Frame */}
                      <div className="w-56 h-36 border-2 border-red-500 rounded-lg relative shadow-lg">
                        {/* Corner decorations */}
                        <div className="absolute -top-1 -left-1 w-6 h-6 border-t-4 border-l-4 border-red-400 rounded-tl-lg"></div>
                        <div className="absolute -top-1 -right-1 w-6 h-6 border-t-4 border-r-4 border-red-400 rounded-tr-lg"></div>
                        <div className="absolute -bottom-1 -left-1 w-6 h-6 border-b-4 border-l-4 border-red-400 rounded-bl-lg"></div>
                        <div className="absolute -bottom-1 -right-1 w-6 h-6 border-b-4 border-r-4 border-red-400 rounded-br-lg"></div>

                        {/* Scanning line */}
                        <div className="absolute inset-x-0 top-1/2 h-0.5 bg-gradient-to-r from-transparent via-red-400 to-transparent animate-pulse shadow-lg" />

                        {/* Pulsing glow effect */}
                        <div className="absolute inset-0 border-2 border-red-400/50 rounded-lg animate-ping"></div>
                      </div>

                      {/* Instructions */}
                      <div className="absolute -top-12 left-1/2 transform -translate-x-1/2">
                        <div className="bg-black/80 backdrop-blur-sm px-4 py-2 rounded-lg border border-red-600/30">
                          <p className="text-white text-sm font-medium whitespace-nowrap">
                            Position barcode within frame
                          </p>
                        </div>
                      </div>
                    </div>
                  </div>
                )}

                {/* Status indicator */}
                <div className="absolute top-4 right-4">
                  <div className="flex items-center gap-2 bg-black/80 backdrop-blur-sm px-3 py-2 rounded-lg border border-red-600/30">
                    <div className="w-2 h-2 bg-red-500 rounded-full animate-pulse"></div>
                    <span className="text-white text-xs font-medium">SCANNING</span>
                  </div>
                </div>
              </div>

              <div className="text-center bg-gray-900/50 rounded-lg p-4 border border-red-800/20">
                <div className="flex items-center justify-center gap-2 mb-2">
                  <ScanLine className="w-4 h-4 text-red-400" />
                  <span className="text-white font-semibold text-sm">Professional Barcode Scanner</span>
                </div>
                <p className="text-gray-300 text-sm mb-1">Hold device steady and ensure good lighting</p>
                <p className="text-gray-400 text-xs">Automatic detection • High precision scanning</p>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

client/src/pages/settings.tsx.content:
import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query";
import { Settings, CreditCard, Calendar, Crown, Check, X, Trash2, AlertTriangle, Bell, Award, Trophy, Flame, Zap } from "lucide-react";
import { Capacitor } from "@capacitor/core";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { useNewAuth } from "@/hooks/useNewAuth";
import ProfileEditor from "@/components/profile-editor";
import type { User } from "@shared/schema";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { useToast } from "@/hooks/use-toast";
import { apiRequest } from "@/lib/queryClient";
import { useState } from "react";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";

interface NotificationPreferences {
  id: string;
  userId: string;
  workoutRemindersEnabled: boolean;
  mealNotificationsEnabled: boolean;
  breakfastTime: string;
  lunchTime: string;
  dinnerTime: string;
  notificationPermissionGranted: boolean;
  createdAt: Date;
  updatedAt: Date;
}

interface UserBadgeWithDetails {
  id: string;
  userId: string;
  badgeId: string;
  earnedAt: Date;
  badge: {
    id: string;
    name: string;
    description: string;
    iconName: string;
    category: string;
    requiredDays: number | null;
    createdAt: Date;
  };
}

export default function SettingsPage() {
  const { user } = useNewAuth() as { user: User | null };
  const { toast } = useToast();
  const queryClient = useQueryClient();
  const [isDeleteDialogOpen, setIsDeleteDialogOpen] = useState(false);

  // Fetch notification preferences
  const { data: notificationPreferences, isLoading: isLoadingPreferences } = useQuery<NotificationPreferences>({
    queryKey: ["/api/notification-preferences"],
    enabled: !!user,
  });

  // Fetch user badges
  const { data: userBadges, isLoading: isLoadingBadges } = useQuery<UserBadgeWithDetails[]>({
    queryKey: ["/api/user/badges"],
    enabled: !!user,
  });

  // Update notification preferences mutation
  const updateNotificationPreferences = useMutation({
    mutationFn: async (updates: Partial<NotificationPreferences>) => {
      const response = await apiRequest("PUT", "/api/notification-preferences", updates);
      return response.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/notification-preferences"] });
      toast({
        title: "Preferences Updated",
        description: "Your notification preferences have been saved.",
      });
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to update notification preferences.",
        variant: "destructive",
      });
    },
  });

  const deleteAccountMutation = useMutation({
    mutationFn: async () => {
      const response = await apiRequest("DELETE", "/api/user/account", {});
      return response.json();
    },
    onSuccess: () => {
      toast({
        title: "Account Deleted",
        description: "Your account and all associated data have been permanently deleted.",
      });
      // Redirect to landing page after a brief delay
      setTimeout(() => {
        window.location.href = "/";
      }, 2000);
    },
    onError: () => {
      toast({
        title: "Error",
        description: "Failed to delete account. Please try again or contact support.",
        variant: "destructive",
      });
    },
  });

  const formatDate = (date: string | Date | null | undefined) => {
    if (!date) return "N/A";
    return new Date(date).toLocaleDateString("en-US", {
      year: "numeric",
      month: "long",
      day: "numeric",
    });
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case "active":
        return <Badge className="bg-green-100 text-green-800 border-green-200"><Check className="w-3 h-3 mr-1" />Active</Badge>;
      case "free_trial":
        return <Badge className="bg-blue-100 text-blue-800 border-blue-200"><Crown className="w-3 h-3 mr-1" />Free Trial</Badge>;
      case "expired":
        return <Badge className="bg-red-100 text-red-800 border-red-200"><X className="w-3 h-3 mr-1" />Expired</Badge>;
      case "inactive":
        return <Badge className="bg-gray-100 text-gray-800 border-gray-200">Inactive</Badge>;
      default:
        return <Badge variant="secondary">{status}</Badge>;
    }
  };

  const getSubscriptionDescription = (status: string) => {
    switch (status) {
      case "active":
        return "You have full access to all premium features including advanced analytics, unlimited workout logging, and priority support.";
      case "free_trial":
        return "You're currently enjoying your free trial with access to all premium features. Upgrade to continue after your trial ends.";
      case "expired":
        return "Your subscription has expired. Upgrade to regain access to premium features and continue your fitness journey.";
      case "inactive":
        return "Your subscription is currently inactive. Reactivate to access premium features.";
      default:
        return "Manage your subscription to access premium features.";
    }
  };

  const getBadgeIcon = (iconName: string) => {
    const iconProps = { className: "w-12 h-12" };
    switch (iconName.toLowerCase()) {
      case "flame":
        return <Flame {...iconProps} className="w-12 h-12 text-orange-500" />;
      case "zap":
        return <Zap {...iconProps} className="w-12 h-12 text-yellow-500" />;
      case "trophy":
        return <Trophy {...iconProps} className="w-12 h-12 text-amber-500" />;
      case "award":
        return <Award {...iconProps} className="w-12 h-12 text-blue-500" />;
      default:
        return <Award {...iconProps} className="w-12 h-12 text-purple-500" />;
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6 space-y-6">
      <div className="flex items-center gap-3 mb-8">
        <Settings className="w-8 h-8 text-primary" />
        <div>
          <h1 className="text-3xl font-bold text-gray-900" data-testid="settings-title">Settings</h1>
          <p className="text-gray-600">Manage your account and subscription preferences</p>
        </div>
      </div>

      {/* Profile Section */}
      <Card data-testid="profile-settings-card">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Settings className="w-5 h-5" />
            Profile Settings
          </CardTitle>
          <CardDescription>
            Update your personal information and profile picture
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-between">
            <div>
              <h3 className="font-medium">Personal Information</h3>
              <p className="text-sm text-gray-600">
                Name: {user?.firstName || user?.lastName 
                  ? `${user.firstName || ''} ${user.lastName || ''}`.trim()
                  : "Not set"}
              </p>
              <p className="text-sm text-gray-600">Email: {user?.email || "Not available"}</p>
            </div>
            <ProfileEditor trigger={
              <Button variant="outline" data-testid="edit-profile-settings">
                Edit Profile
              </Button>
            } />
          </div>
        </CardContent>
      </Card>

      {/* Notification Preferences Section */}
      <Card data-testid="notification-settings-card">
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Bell className="w-5 h-5" />
            Notification Preferences
          </CardTitle>
          <CardDescription>
            Manage workout reminders and meal time notifications
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-6">
          {isLoadingPreferences ? (
            <p className="text-sm text-gray-500">Loading preferences...</p>
          ) : (
            <>
              {/* Workout Reminders */}
              <div className="flex items-center justify-between">
                <div className="space-y-0.5">
                  <Label htmlFor="workout-reminders" className="text-base">
                    Workout Reminders
                  </Label>
                  <p className="text-sm text-gray-500">
                    Get notified if you haven't logged a workout in 24 hours
                  </p>
                </div>
                <Switch
                  id="workout-reminders"
                  checked={notificationPreferences?.workoutRemindersEnabled ?? true}
                  onCheckedChange={(checked) => {
                    updateNotificationPreferences.mutate({ workoutRemindersEnabled: checked });
                  }}
                  data-testid="switch-workout-reminders"
                />
              </div>

              <Separator />

              {/* Meal Notifications */}
              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <div className="space-y-0.5">
                    <Label htmlFor="meal-notifications" className="text-base">
                      Meal Time Notifications
                    </Label>
                    <p className="text-sm text-gray-500">
                      Receive reminders for breakfast, lunch, and dinner times
                    </p>
                  </div>
                  <Switch
                    id="meal-notifications"
                    checked={notificationPreferences?.mealNotificationsEnabled ?? true}
                    onCheckedChange={(checked) => {
                      updateNotificationPreferences.mutate({ mealNotificationsEnabled: checked });
                    }}
                    data-testid="switch-meal-notifications"
                  />
                </div>

                {notificationPreferences?.mealNotificationsEnabled && (
                  <div className="ml-4 space-y-4 pl-4 border-l-2 border-gray-200">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div className="space-y-2">
                        <Label htmlFor="breakfast-time">Breakfast Time</Label>
                        <Input
                          id="breakfast-time"
                          type="time"
                          value={notificationPreferences?.breakfastTime || "08:00"}
                          onChange={(e) => {
                            updateNotificationPreferences.mutate({ breakfastTime: e.target.value });
                          }}
                          data-testid="input-breakfast-time"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="lunch-time">Lunch Time</Label>
                        <Input
                          id="lunch-time"
                          type="time"
                          value={notificationPreferences?.lunchTime || "12:00"}
                          onChange={(e) => {
                            updateNotificationPreferences.mutate({ lunchTime: e.target.value });
                          }}
                          data-testid="input-lunch-time"
                        />
                      </div>
                      <div className="space-y-2">
                        <Label htmlFor="dinner-time">Dinner Time</Label>
                        <Input
                          id="dinner-time"
                          type="time"
                          value={notificationPreferences?.dinnerTime || "18:00"}
                          onChange={(e) => {
                            updateNotificationPreferences.mutate({ dinnerTime: e.target.value });
                          }}
                          data-testid="input-dinner-time"
                        />
                      </div>
                    </div>
                  </div>
                )}
              </div>

              <Separator />

