  isPublic: boolean("is_public").default(false), // allow sharing in community
  createdAt: timestamp("created_at").defaultNow().notNull(),
});

// Progress Photos insert schemas
export const insertProgressPhotoSchema = createInsertSchema(progressPhotos).omit({
  id: true,
  createdAt: true,
});

// Progress Photos types
export type InsertProgressPhoto = z.infer<typeof insertProgressPhotoSchema>;
export type ProgressPhoto = typeof progressPhotos.$inferSelect;

// Extended types for API responses
export type ProgressPhotoWithWorkout = ProgressPhoto & {
  workout?: {
    id: string;
    name: string;
    category: string;
    date: Date;
  };
};

// Notification Preferences for workout reminders and meal times
export const notificationPreferences = pgTable("notification_preferences", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").references(() => users.id).notNull().unique(),
  workoutRemindersEnabled: boolean("workout_reminders_enabled").default(true).notNull(),
  mealNotificationsEnabled: boolean("meal_notifications_enabled").default(true).notNull(),
  breakfastTime: varchar("breakfast_time").default("08:00"), // HH:MM format
  lunchTime: varchar("lunch_time").default("12:00"), // HH:MM format
  dinnerTime: varchar("dinner_time").default("18:00"), // HH:MM format
  lastWorkoutReminderSent: timestamp("last_workout_reminder_sent"),
  notificationPermissionGranted: boolean("notification_permission_granted").default(false),
  createdAt: timestamp("created_at").defaultNow().notNull(),
  updatedAt: timestamp("updated_at").defaultNow().notNull(),
});

// Subscription Audit Table for tracking subscription state changes
export const subscriptionAudit = pgTable("subscription_audit", {
  id: varchar("id").primaryKey().default(sql`gen_random_uuid()`),
  userId: varchar("user_id").references(() => users.id).notNull(),
  fromStatus: varchar("from_status").notNull(),
  toStatus: varchar("to_status").notNull(),
  reason: varchar("reason").notNull(), // trial_expired, payment_success, payment_failed, cancelled, etc.
  timestamp: timestamp("timestamp").defaultNow().notNull(),
  metadata: jsonb("metadata"), // Additional data like Stripe event ID, error details, etc.
});

// Notification Preferences insert schema
export const insertNotificationPreferencesSchema = createInsertSchema(notificationPreferences).omit({
  id: true,
  createdAt: true,
  updatedAt: true,
});

// Notification Preferences types
export type InsertNotificationPreferences = z.infer<typeof insertNotificationPreferencesSchema>;
export type NotificationPreferences = typeof notificationPreferences.$inferSelect;

// Subscription Audit insert schema
export const insertSubscriptionAuditSchema = createInsertSchema(subscriptionAudit).omit({
  id: true,
  timestamp: true,
});

// Subscription Audit types
export type InsertSubscriptionAudit = z.infer<typeof insertSubscriptionAuditSchema>;
export type SubscriptionAudit = typeof subscriptionAudit.$inferSelect;

// Premium Features Definition
export const PREMIUM_FEATURES = {
  WORKOUT_PLANNER: 'workout_planner',
  MILE_TRACKER: 'mile_tracker',
  MEAL_PLANS: 'meal_plans',
  MEAL_TRACKER: 'meal_tracker',
  PROGRESS_PHOTOS: 'progress_photos'
} as const;

export type PremiumFeature = typeof PREMIUM_FEATURES[keyof typeof PREMIUM_FEATURES];

// Premium-only features (no trial access) - subscription required
export const PREMIUM_ONLY_FEATURES: PremiumFeature[] = [
  PREMIUM_FEATURES.WORKOUT_PLANNER,
  PREMIUM_FEATURES.MEAL_PLANS,
  PREMIUM_FEATURES.MEAL_TRACKER
];

// Feature access helper function
export const isPremiumFeature = (feature: string): feature is PremiumFeature => {
  return Object.values(PREMIUM_FEATURES).includes(feature as PremiumFeature);
};

// Check if feature requires active subscription (no trial access)
export const isPremiumOnlyFeature = (feature: PremiumFeature): boolean => {
  return PREMIUM_ONLY_FEATURES.includes(feature);
};

// Trial expiration checker
export const isTrialExpired = (user: { trialEndDate: Date | null; subscriptionStatus: string }): boolean => {
  if (!user.trialEndDate) return true;
  return user.subscriptionStatus === 'free_trial' && new Date() > new Date(user.trialEndDate);
};

// Feature access checker
export const hasFeatureAccess = (user: { subscriptionStatus: string; trialEndDate: Date | null }, feature: PremiumFeature): boolean => {
  // Active subscription has access to everything
  if (user.subscriptionStatus === 'active') return true;

  // Check if feature is premium-only (requires subscription, no trial access)
  if (isPremiumOnlyFeature(feature)) return false;

  // For non-premium-only features, trial users have access if trial hasn't expired
  if (user.subscriptionStatus === 'free_trial' && !isTrialExpired(user)) return true;

  return false;
};

// Authentication types
export type SignUpData = z.infer<typeof signUpSchema>;
export type SignInData = z.infer<typeof signInSchema>;

