server/mealPlanGenerator.ts.content:
import OpenAI from "openai";
import { getMealImageUrl, getIngredientImageUrl } from "./imageService";

// the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
const openai = new OpenAI({
  apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY || process.env.OPENAI_API_KEY,
  baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL
});

export interface MealPlanGenerationOptions {
  goal: "weight_loss" | "weight_gain" | "maintenance";
  dailyCalories: number;
  dietaryRestrictions?: string[];
  preferences?: string[];
  allergies?: string[];
  mealsPerDay?: number;
  duration?: number; // days
}

export interface GeneratedMealPlan {
  name: string;
  description: string;
  goal: string;
  dailyCalories: number;
  dailyProtein: number;
  dailyCarbs: number;
  dailyFat: number;
  duration: number;
  days: {
    dayNumber: number;
    name: string;
    meals: {
      mealType: "breakfast" | "lunch" | "dinner" | "snack";
      name: string;
      description: string;
      calories: number;
      protein: number;
      carbs: number;
      fat: number;
      ingredients: string[];
      instructions: string[];
      prepTime: number;
      servings: number;
      imageUrl?: string;
      ingredientImages?: Record<string, string>;
    }[];
  }[];
}


// Enhanced meal plan generator with user food preferences
async function generateMockMealPlan(options: MealPlanGenerationOptions): Promise<GeneratedMealPlan> {
  const {
    goal,
    dailyCalories,
    dietaryRestrictions = [],
    preferences = [],
    allergies = [],
    duration = 7
  } = options;

  // Calculate macros based on goal
  let proteinPercent = 0.25; // 25% protein
  let carbPercent = 0.45; // 45% carbs
  let fatPercent = 0.30; // 30% fat

  if (goal === 'weight_loss') {
    proteinPercent = 0.30;
    carbPercent = 0.35;
    fatPercent = 0.35;
  } else if (goal === 'weight_gain') {
    proteinPercent = 0.25;
    carbPercent = 0.50;
    fatPercent = 0.25;
  }

  const dailyProtein = Math.round((dailyCalories * proteinPercent) / 4);
  const dailyCarbs = Math.round((dailyCalories * carbPercent) / 4);
  const dailyFat = Math.round((dailyCalories * fatPercent) / 9);

