// New interface for personalized meal plans with food preferences
interface PersonalizedMealPlanParams {
  goal: string; 
  dailyCalories: number;
  duration: number;
  likedFoods: string[];
  dislikedFoods: string[];
  userId: string;
  dietaryRestrictions?: string[];
  allergies?: string[];
  preferences?: string[];
}

export async function generatePersonalizedMealPlan(params: PersonalizedMealPlanParams | MealPlanGenerationOptions): Promise<GeneratedMealPlan> {
  // Handle both old and new interface
  if ('likedFoods' in params) {
    return generatePersonalizedMealPlanWithFoodPreferences(params as PersonalizedMealPlanParams);
  }

  const options = params as MealPlanGenerationOptions;
  if (!process.env.OPENAI_API_KEY) {
    console.log("OPENAI_API_KEY not configured, using mock meal plan");
    return generateMockMealPlan(options);
  }

  const {
    goal,
    dailyCalories,
    dietaryRestrictions = [],
    preferences = [],
    allergies = [],
    mealsPerDay = 4,
    duration = 7
  } = options;

  try {
    const response = await openai.chat.completions.create({
      model: "gpt-5", // the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
      messages: [
        {
          role: "system",
          content: `You are a certified nutritionist and meal planning expert. Create personalized meal plans based on user goals and preferences.

Key requirements:
1. Create balanced meals that meet the daily caloric and macro targets
2. Ensure meals are practical, affordable, and easy to prepare
3. Include variety across the week to prevent boredom
4. Consider dietary restrictions, allergies, and preferences
5. Provide detailed nutritional breakdowns for each meal
6. Include clear, step-by-step cooking instructions
7. Estimate realistic preparation times

Respond with JSON in this exact format:
{
  "name": "Descriptive meal plan name based on goal",
  "description": "Brief description of the meal plan and its benefits",
  "goal": "${goal}",
  "dailyCalories": ${dailyCalories},
  "dailyProtein": number (grams - target 20-30% of calories),
  "dailyCarbs": number (grams - adjust based on goal),
  "dailyFat": number (grams - 20-35% of calories),
  "duration": ${duration},
  "days": [
    {
      "dayNumber": 1,
      "name": "Day 1",
      "meals": [
        {
          "mealType": "breakfast/lunch/dinner/snack",
          "name": "Meal name",
          "description": "Brief description",
          "calories": number,
          "protein": number (grams),
          "carbs": number (grams),
          "fat": number (grams),
          "ingredients": ["ingredient 1", "ingredient 2"],
          "instructions": ["step 1", "step 2"],
          "prepTime": number (minutes),
          "servings": 1
        }
      ]
    }
  ]
}`
        },
        {
          role: "user",
          content: `Create a ${duration}-day meal plan with the following specifications:

Goal: ${goal}
Daily Calories: ${dailyCalories}
Meals per day: ${mealsPerDay}
${dietaryRestrictions.length > 0 ? `Dietary Restrictions: ${dietaryRestrictions.join(', ')}` : ''}
${allergies.length > 0 ? `Allergies: ${allergies.join(', ')}` : ''}
${preferences.length > 0 ? `Preferences: ${preferences.join(', ')}` : ''}

GOAL-SPECIFIC GUIDELINES:
${goal === 'weight_loss' ? `WEIGHT LOSS:
- Focus on high-volume, low-calorie foods (vegetables, lean proteins)
- Emphasize foods that promote satiety (high protein, high fiber)
- Include plenty of leafy greens and non-starchy vegetables
- Use lean cooking methods (grilling, baking, steaming)
- Smaller portion sizes with nutrient-dense foods
- Examples: Grilled chicken salads, vegetable stir-fries, egg white omelets` : ''}
${goal === 'weight_gain' ? `WEIGHT GAIN:
- Focus on calorie-dense, nutrient-rich foods
- Include healthy fats (nuts, avocado, olive oil, nut butters)
- Emphasize complex carbs and starches (rice, pasta, potatoes, oats)
- Larger portion sizes with added healthy calories
- Include smoothies, shakes, and energy-dense snacks
- Examples: Peanut butter toast, pasta dishes, rice bowls, protein pancakes` : ''}
${goal === 'maintenance' ? `MAINTENANCE:
- Balance between all food groups
- Moderate portions with variety
- Include a mix of lean proteins, whole grains, healthy fats
- Focus on sustainable, enjoyable meals` : ''}

IMPORTANT CONSTRAINTS:
- MUST create distinctly different meals based on the goal (weight loss vs weight gain meals should be VERY different)
- Include MAXIMUM variety - no repeated meals across the ${duration} days
- Every day should feature different meals and different ingredients
- Focus on whole, minimally processed foods

Please ensure each day's meals total approximately ${dailyCalories} calories and provide a good balance of macronutrients. Make the meals practical for someone with basic cooking skills.`
        }
      ],
      response_format: { type: "json_object" },
      max_completion_tokens: 4000,
    });

    const result = JSON.parse(response.choices[0].message.content || "{}");

    // Validate the structure
    if (!result.name || !result.days || !Array.isArray(result.days)) {
      throw new Error("Invalid meal plan structure generated");
    }

    // Ensure we have the right number of days
    if (result.days.length !== duration) {
      throw new Error(`Expected ${duration} days, got ${result.days.length}`);
    }

    // Validate each day has meals and add image URLs
    for (const day of result.days) {
      if (!day.meals || !Array.isArray(day.meals) || day.meals.length === 0) {
        throw new Error(`Day ${day.dayNumber} has no meals`);
      }

      // Add image URLs to each meal
      for (const meal of day.meals) {
        meal.imageUrl = await getMealImageUrl(meal.mealType, meal.name);

        // Add ingredient images
        if (meal.ingredients && Array.isArray(meal.ingredients)) {
          meal.ingredientImages = {};
          for (const ingredient of meal.ingredients) {
            meal.ingredientImages[ingredient] = await getIngredientImageUrl(ingredient);
          }
        }
      }
    }

    return result as GeneratedMealPlan;
  } catch (error) {
    console.error("Error generating meal plan:", error);

    // Fallback to mock data if OpenAI API fails
    console.log("OpenAI API failed, falling back to mock meal plan");
    return generateMockMealPlan(options);
  }
}

export async function generateWeeklyMealPlan(
  userId: string,
  userPreferences: {
    goal: "weight_loss" | "weight_gain" | "maintenance";
    dailyCalories: number;
    dietaryRestrictions?: string[];
    preferences?: string[];
    allergies?: string[];
  }
): Promise<GeneratedMealPlan> {
  const options: MealPlanGenerationOptions = {
    ...userPreferences,
    duration: 7,
    mealsPerDay: 4
  };

  return generatePersonalizedMealPlan(options);
}

async function generatePersonalizedMealPlanWithFoodPreferences(params: PersonalizedMealPlanParams): Promise<GeneratedMealPlan> {
  const { 
    goal, 
    dailyCalories, 
    duration, 
    likedFoods, 
    dislikedFoods, 
    userId,
    dietaryRestrictions = [],
    allergies = [],
    preferences = []
  } = params;

  console.log(`Generating personalized meal plan for user ${userId}:`, {
    goal,
    dailyCalories,
    duration,
    likedFoodsCount: likedFoods.length,
    dislikedFoodsCount: dislikedFoods.length,
    dietaryRestrictions,
    allergies,
    preferences
  });

  if (!process.env.OPENAI_API_KEY) {
    console.log("OPENAI_API_KEY not configured, using mock meal plan");
    return generateMockMealPlan({
      goal: goal as any,
      dailyCalories,
      duration,
      preferences: likedFoods,
      dietaryRestrictions: dislikedFoods.map(food => `Avoid ${food}`)
    });
  }

  // Calculate macronutrient targets based on goal
  const proteinPercentage = goal === "weight_gain" ? 0.25 : goal === "weight_loss" ? 0.30 : 0.25;
  const fatPercentage = goal === "weight_gain" ? 0.30 : 0.25;
  const carbPercentage = 1 - proteinPercentage - fatPercentage;

  const dailyProtein = Math.round((dailyCalories * proteinPercentage) / 4); // 4 cal per gram
  const dailyFat = Math.round((dailyCalories * fatPercentage) / 9); // 9 cal per gram  
  const dailyCarbs = Math.round((dailyCalories * carbPercentage) / 4); // 4 cal per gram

  const goalDescription = goal === "weight_loss" ? 
    "weight loss with moderate calorie deficit" : 
    goal === "weight_gain" ? 
    "healthy weight gain with calorie surplus" : 
    "weight maintenance and overall health";

  // Goal-specific meal guidance
  const goalGuidance = goal === "weight_loss" 
    ? `WEIGHT LOSS SPECIFIC GUIDELINES:
- Focus on high-volume, low-calorie foods (vegetables, lean proteins)
- Emphasize foods that promote satiety (high protein, high fiber)
- Include plenty of leafy greens and non-starchy vegetables
- Use lean cooking methods (grilling, baking, steaming)
- Smaller portion sizes with nutrient-dense foods
- Examples: Grilled chicken salads, vegetable stir-fries, egg white omelets, Greek yogurt bowls`
    : goal === "weight_gain"
    ? `WEIGHT GAIN SPECIFIC GUIDELINES:
- Focus on calorie-dense, nutrient-rich foods
- Include healthy fats (nuts, avocado, olive oil, nut butters)
- Emphasize complex carbs and starches (rice, pasta, potatoes, oats)
- Larger portion sizes with added healthy calories
- Include smoothies, shakes, and energy-dense snacks
- Examples: Peanut butter toast, pasta dishes, rice bowls, protein pancakes, trail mix, smoothie bowls`
    : `MAINTENANCE SPECIFIC GUIDELINES:
- Balance between all food groups
- Moderate portions with variety
- Include a mix of lean proteins, whole grains, healthy fats
- Focus on sustainable, enjoyable meals
- Examples: Balanced grain bowls, mixed protein sources, variety of vegetables`;

  const prompt = `Create a ${duration}-day personalized meal plan for ${goalDescription}.

REQUIREMENTS:
- Daily calories: ${dailyCalories}
- Daily protein: ${dailyProtein}g
- Daily carbs: ${dailyCarbs}g  
- Daily fat: ${dailyFat}g
- 4 meals per day: breakfast, lunch, dinner, snack

${goalGuidance}

FOOD PREFERENCES:
Preferred foods (use these heavily): ${likedFoods.length > 0 ? likedFoods.join(", ") : "No specific preferences"}
Foods to avoid: ${dislikedFoods.length > 0 ? dislikedFoods.join(", ") : "None"}
${dietaryRestrictions.length > 0 ? `Dietary restrictions: ${dietaryRestrictions.join(", ")}` : ""}
${allergies.length > 0 ? `Allergies (MUST avoid): ${allergies.join(", ")}` : ""}
${preferences.length > 0 ? `General preferences: ${preferences.join(", ")}` : ""}

IMPORTANT CONSTRAINTS:
- MUST create distinctly different meals based on the goal (weight loss vs weight gain meals should be VERY different)
- Focus on whole, minimally processed foods
- Include MAXIMUM variety - no repeated meals across the ${duration} days
- Ensure adequate micronutrient coverage
- Make meals practical and realistic
- Each meal should have clear portions and instructions
- Every day should feature different meals and different ingredients

Respond with JSON in this exact format:
{
  "name": "string",
  "description": "string", 
  "goal": "${goal}",
  "dailyCalories": ${dailyCalories},
  "dailyProtein": ${dailyProtein},
  "dailyCarbs": ${dailyCarbs},
  "dailyFat": ${dailyFat},
  "duration": ${duration},
  "days": [
    {
      "dayNumber": 1,
      "name": "Day 1",
      "meals": [
        {
          "mealType": "breakfast",
          "name": "string",
          "description": "string",
          "calories": number,
          "protein": number,
          "carbs": number, 
          "fat": number,
          "ingredients": ["string"],
          "instructions": ["string"],
          "prepTime": number,
          "servings": 1
        }
      ]
    }
  ]
}`;

  try {
    const response = await openai.chat.completions.create({
      model: "gpt-5", // the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
      messages: [
        {
          role: "system",
          content: "You are a professional nutritionist and meal planning expert. Create detailed, nutritionally balanced meal plans based on user preferences and goals. Always respond with valid JSON only."
        },
        {
          role: "user",
          content: prompt
        }
      ],
      response_format: { type: "json_object" },
      temperature: 0.7,
      max_completion_tokens: 4000
    });

    const content = response.choices[0].message.content;
    if (!content) {
      throw new Error("No content received from AI");
    }

    const generatedPlan = JSON.parse(content);

    // Validate the response structure
    if (!generatedPlan.name || !generatedPlan.days || !Array.isArray(generatedPlan.days)) {
      throw new Error("Invalid meal plan structure received from AI");
    }

    // Ensure each day has the required meal types and add image URLs
    for (let dayIndex = 0; dayIndex < generatedPlan.days.length; dayIndex++) {
      const day = generatedPlan.days[dayIndex];

      if (!day.meals || !Array.isArray(day.meals)) {
        throw new Error(`Day ${dayIndex + 1} is missing meals array`);
      }

      const mealTypes = day.meals.map((meal: any) => meal.mealType);
      const requiredTypes = ["breakfast", "lunch", "dinner", "snack"];

      requiredTypes.forEach(type => {
        if (!mealTypes.includes(type)) {
          console.warn(`Day ${dayIndex + 1} is missing ${type} meal`);
        }
      });

      // Add image URLs to each meal
      for (const meal of day.meals) {
        meal.imageUrl = await getMealImageUrl(meal.mealType, meal.name);

        // Add ingredient images
        if (meal.ingredients && Array.isArray(meal.ingredients)) {
          meal.ingredientImages = {};
          for (const ingredient of meal.ingredients) {
            meal.ingredientImages[ingredient] = await getIngredientImageUrl(ingredient);
          }
        }
      }
    }

    console.log(`Successfully generated ${duration}-day meal plan: "${generatedPlan.name}"`);
    return generatedPlan as GeneratedMealPlan;

  } catch (error: any) {
    console.error("Error generating personalized meal plan:", error);

    if (error.message?.includes("API key")) {
      throw new Error("OpenAI API key is not configured. Please set OPENAI_API_KEY environment variable.");
    }

    if (error.message?.includes("JSON")) {
      throw new Error("Failed to parse AI response. Please try again.");
    }

    throw new Error(`Failed to generate meal plan: ${error.message}`);
  }
}

server/auto-difficulty-adjuster.ts.content:
import { storage } from "./storage";
import { aiDifficultyService } from "./ai-difficulty-service";
import type { User, Exercise } from "../shared/schema";

export interface AutoAdjustmentResult {
  userId: string;
  exerciseId: string;
  currentDifficulty: number;
  suggestedDifficulty: number;
  adjustmentReason: string;
  confidence: number;
  shouldNotify: boolean;
}

export class AutoDifficultyAdjuster {
  /**
   * Analyzes all users and their workout patterns to suggest difficulty adjustments
   */
  async processAllUsers(): Promise<AutoAdjustmentResult[]> {
    const users = await storage.getUsers();
    const adjustmentResults: AutoAdjustmentResult[] = [];

    for (const user of users) {
      const userAdjustments = await this.processUserAdjustments(user.id);
      adjustmentResults.push(...userAdjustments);
    }

    return adjustmentResults;
  }

  /**
   * Processes difficulty adjustments for a specific user
   */
  async processUserAdjustments(userId: string): Promise<AutoAdjustmentResult[]> {
    try {
      // Get user's recent workouts to identify exercises they've been doing
      const recentWorkouts = await storage.getWorkouts(userId);

      if (recentWorkouts.length === 0) {
        return [];
      }

      // Get unique exercises from recent workouts
      const uniqueExerciseIds = new Set<string>();

      // Get workout exercises for each recent workout to find unique exercises
      for (const workout of recentWorkouts.slice(0, 10)) { // Last 10 workouts
        const workoutExercises = await storage.getWorkoutExercises(workout.id);
        workoutExercises.forEach(we => uniqueExerciseIds.add(we.exerciseId));
      }

      const adjustmentResults: AutoAdjustmentResult[] = [];

      // Analyze each exercise for potential difficulty adjustments
      for (const exerciseId of uniqueExerciseIds) {
        const analysis = await aiDifficultyService.analyzePerformanceAndSuggestDifficulty(
          userId,
          exerciseId
        );

        if (analysis && this.shouldSuggestAdjustment(analysis)) {
          const exercise = await storage.getExercise(exerciseId);

          adjustmentResults.push({
            userId,
            exerciseId,
            currentDifficulty: analysis.currentDifficulty,
            suggestedDifficulty: analysis.suggestedDifficulty,
            adjustmentReason: this.generateAdjustmentReason(analysis),
            confidence: analysis.confidenceScore,
            shouldNotify: analysis.confidenceScore >= 70, // Only notify for high-confidence suggestions
          });
        }
      }

      return adjustmentResults;
    } catch (error) {
      console.error(`Error processing user adjustments for ${userId}:`, error);
      return [];
    }
  }

  /**
   * Determines if an adjustment should be suggested based on AI analysis
   */
  private shouldSuggestAdjustment(analysis: any): boolean {
    // Don't suggest if confidence is too low
    if (analysis.confidenceScore < 50) return false;

    // Don't suggest if the change is minimal
    const difficultyChange = Math.abs(analysis.suggestedDifficulty - analysis.currentDifficulty);
    if (difficultyChange < 0.5) return false;

    // Don't suggest extreme changes
    if (difficultyChange > 2) return false;

    // Additional logic based on performance trends
    if (analysis.performanceTrend === "declining" && analysis.suggestedDifficulty > analysis.currentDifficulty) {
      // Don't increase difficulty if performance is declining unless confidence is very high
      return analysis.confidenceScore >= 80;
    }

    return true;
  }

  /**
   * Generates a human-readable reason for the difficulty adjustment
   */
  private generateAdjustmentReason(analysis: any): string {
    const { performanceTrend, currentDifficulty, suggestedDifficulty, reasoningFactors } = analysis;
    const isIncrease = suggestedDifficulty > currentDifficulty;

    if (performanceTrend === "improving") {
      if (isIncrease) {
        return `Your performance has been consistently improving! Time to challenge yourself with a higher difficulty.`;
      } else {
        return `You're improving steadily. Consider maintaining current difficulty for better consistency.`;
      }
    } else if (performanceTrend === "declining") {
      if (!isIncrease) {
        return `Recent workouts show some struggle. Let's dial back the difficulty to rebuild confidence and form.`;
      } else {
        return `Despite some challenges, your overall trend shows readiness for progression.`;
      }
    } else {
      // Stable performance
      if (isIncrease) {
        return `Your performance is stable and consistent. Ready to take on a new challenge!`;
      } else {
        return `Let's optimize your current level before progressing to maintain quality workouts.`;
      }
    }
  }

  /**
   * Applies automatic difficulty adjustments for a user (with their consent)
   */
  async applyAutomaticAdjustments(userId: string, exerciseIds: string[]): Promise<boolean[]> {
    const results: boolean[] = [];

    for (const exerciseId of exerciseIds) {
      try {
        // Get pending adjustments for this user and exercise
        const pendingAdjustments = await aiDifficultyService.getPendingAdjustments(userId);
        const relevantAdjustment = pendingAdjustments.find(adj => adj.exerciseId === exerciseId);

        if (relevantAdjustment) {
          const applied = await aiDifficultyService.applyDifficultyAdjustment(relevantAdjustment.id);
          results.push(applied);
        } else {
          results.push(false);
        }
      } catch (error) {
        console.error(`Error applying adjustment for exercise ${exerciseId}:`, error);
        results.push(false);
      }
    }

    return results;
  }

  /**
   * Gets intelligent workout recommendations based on user's performance patterns
   */
  async getIntelligentRecommendations(userId: string): Promise<{
    exercises: Array<{
      exerciseId: string;
      exerciseName: string;
      recommendedDifficulty: number;
      reason: string;
      confidence: number;
    }>;
    overallRecommendation: string;
  }> {
    try {
      const adjustments = await this.processUserAdjustments(userId);
      const exercises = [];

      for (const adjustment of adjustments) {
        const exercise = await storage.getExercise(adjustment.exerciseId);
        if (exercise) {
          exercises.push({
            exerciseId: adjustment.exerciseId,
            exerciseName: exercise.name,
            recommendedDifficulty: adjustment.suggestedDifficulty,
            reason: adjustment.adjustmentReason,
            confidence: adjustment.confidence,
          });
        }
      }

      // Generate overall recommendation
      let overallRecommendation = "Keep up the great work! ";

      const increasingCount = adjustments.filter(a => a.suggestedDifficulty > a.currentDifficulty).length;
      const decreasingCount = adjustments.filter(a => a.suggestedDifficulty < a.currentDifficulty).length;

      if (increasingCount > decreasingCount) {
        overallRecommendation += "You're ready to challenge yourself with higher difficulty levels across multiple exercises.";
      } else if (decreasingCount > increasingCount) {
        overallRecommendation += "Focus on form and consistency. Consider reducing difficulty to build a strong foundation.";
      } else {
        overallRecommendation += "Your training is well-balanced. Make selective adjustments based on individual exercise performance.";
      }

      return {
        exercises: exercises.slice(0, 5), // Limit to top 5 recommendations
        overallRecommendation,
      };
    } catch (error) {
      console.error(`Error generating recommendations for user ${userId}:`, error);
      return {
        exercises: [],
        overallRecommendation: "Unable to generate recommendations at this time. Please try again later.",
      };
    }
  }

  /**
   * Runs the daily auto-adjustment process for all users
   */
  async runDailyAdjustmentProcess(): Promise<{
    processed: number;
    adjustmentsSuggested: number;
    highConfidenceAdjustments: number;
  }> {
    console.log("Starting daily auto-adjustment process...");

    const allAdjustments = await this.processAllUsers();
    const highConfidenceAdjustments = allAdjustments.filter(adj => adj.shouldNotify);

    console.log(`Processed ${allAdjustments.length} potential adjustments`);
    console.log(`${highConfidenceAdjustments.length} high-confidence adjustments ready for notification`);

    return {
      processed: allAdjustments.length,
      adjustmentsSuggested: allAdjustments.length,
      highConfidenceAdjustments: highConfidenceAdjustments.length,
    };
  }
}

export const autoDifficultyAdjuster = new AutoDifficultyAdjuster();

