  // AI Difficulty Adjustments implementation
  async getRecentWorkoutsForExercise(userId: string, exerciseId: string, limit: number): Promise<(Workout & { exercises: WorkoutExercise[] })[]> {
    const allWorkouts = Array.from(this.workouts.values())
      .filter(workout => workout.userId === userId)
      .sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());

    const workoutsWithExercises: (Workout & { exercises: WorkoutExercise[] })[] = [];

    for (const workout of allWorkouts) {
      const workoutExercises = Array.from(this.workoutExercises.values())
        .filter(we => we.workoutId === workout.id && we.exerciseId === exerciseId);

      if (workoutExercises.length > 0) {
        workoutsWithExercises.push({
          ...workout,
          exercises: workoutExercises
        });

        if (workoutsWithExercises.length >= limit) {
          break;
        }
      }
    }

    return workoutsWithExercises;
  }

  async createAiDifficultyAdjustment(adjustment: InsertAiDifficultyAdjustment): Promise<AiDifficultyAdjustment> {
    const id = randomUUID();
    const now = new Date();
    const newAdjustment: AiDifficultyAdjustment = {
      id,
      ...adjustment,
      createdAt: now,
      updatedAt: now,
    };
    this.aiDifficultyAdjustments.set(id, newAdjustment);
    return newAdjustment;
  }

  async getPendingAiAdjustments(userId: string): Promise<AiDifficultyAdjustment[]> {
    return Array.from(this.aiDifficultyAdjustments.values())
      .filter(adjustment => adjustment.userId === userId && !adjustment.applied)
      .sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }

  async applyAiDifficultyAdjustment(adjustmentId: string): Promise<boolean> {
    const adjustment = this.aiDifficultyAdjustments.get(adjustmentId);
    if (!adjustment) {
      return false;
    }

    const updatedAdjustment = {
      ...adjustment,
      applied: true,
      appliedAt: new Date(),
      updatedAt: new Date(),
    };

    this.aiDifficultyAdjustments.set(adjustmentId, updatedAdjustment);
    return true;
  }

  // Meal Tracking methods implementation
  async getMealEntries(userId: string, date?: string): Promise<MealEntry[]> {
    const entries = Array.from(this.mealEntries.values()).filter(entry => entry.userId === userId);

    if (date) {
      const targetDate = new Date(date);
      return entries.filter(entry => {
        const entryDate = new Date(entry.loggedAt);
        return entryDate.toDateString() === targetDate.toDateString();
      });
    }

    return entries.sort((a, b) => new Date(b.loggedAt).getTime() - new Date(a.loggedAt).getTime());
  }

  async createMealEntry(entry: InsertMealEntry): Promise<MealEntry> {
    const id = randomUUID();
    const newEntry: MealEntry = {
      ...entry,
      id,
      loggedAt: entry.loggedAt || new Date(),
    };

    this.mealEntries.set(id, newEntry);

    // Update user activity to maintain streak
    await this.updateUserActivity(entry.userId, newEntry.loggedAt);

    return newEntry;
  }

  async getMealEntry(id: string): Promise<MealEntry | undefined> {
    return this.mealEntries.get(id);
  }

  async deleteMealEntry(id: string): Promise<boolean> {
    return this.mealEntries.delete(id);
  }

  // Workout Planner methods
  async getWorkoutPreferences(userId: string): Promise<WorkoutPreferences | undefined> {
    return Array.from(this.workoutPreferences.values()).find(p => p.userId === userId);
  }

  async saveWorkoutPreferences(preferences: InsertWorkoutPreferences): Promise<WorkoutPreferences> {
    const id = randomUUID();
    const workoutPreferences: WorkoutPreferences = {
      ...preferences,
      id,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    // Remove any existing preferences for this user
    for (const [key, existing] of this.workoutPreferences.entries()) {
      if (existing.userId === preferences.userId) {
        this.workoutPreferences.delete(key);
        break;
      }
    }

    this.workoutPreferences.set(id, workoutPreferences);
    return workoutPreferences;
  }

  async getWorkoutPlan(userId: string): Promise<(WorkoutPlan & { plannedWorkouts: PlannedWorkout[] }) | undefined> {
    const plan = Array.from(this.workoutPlans.values()).find(p => p.userId === userId && p.isActive);
    if (!plan) return undefined;

    const plannedWorkouts = Array.from(this.plannedWorkouts.values())
      .filter(pw => pw.planId === plan.id);

    return {
      ...plan,
      plannedWorkouts
    };
  }

  async createWorkoutPlan(plan: InsertWorkoutPlan): Promise<WorkoutPlan> {
    const id = randomUUID();
    const workoutPlan: WorkoutPlan = {
      ...plan,
      id,
      createdAt: new Date(),
      updatedAt: new Date(),
    };

    // Deactivate any existing active plans for this user
    for (const [key, existing] of this.workoutPlans.entries()) {
      if (existing.userId === plan.userId && existing.isActive) {
        this.workoutPlans.set(key, { ...existing, isActive: false, updatedAt: new Date() });
      }
    }

    this.workoutPlans.set(id, workoutPlan);
    return workoutPlan;
  }

  async createPlannedWorkouts(plannedWorkouts: InsertPlannedWorkout[]): Promise<PlannedWorkout[]> {
    const result: PlannedWorkout[] = [];

    for (const plannedWorkout of plannedWorkouts) {
      const id = randomUUID();
      const workout: PlannedWorkout = {
        ...plannedWorkout,
        id,
        createdAt: new Date(),
        updatedAt: new Date(),
      };

      this.plannedWorkouts.set(id, workout);
      result.push(workout);
    }

    return result;
  }
}

// Database Storage Implementation
export class DatabaseStorage implements IStorage {
  // Authentication methods
  async createUserWithPassword(userData: SignUpData): Promise<User> {
    try {
      // Check if username or email already exists
      const existingUser = await this.getUserByUsernameOrEmail(userData.username) || 
                          await this.getUserByUsernameOrEmail(userData.email);

      if (existingUser) {
        throw new Error("Username or email already exists");
      }

      // Hash the password
      const saltRounds = 12;
      const passwordHash = await bcrypt.hash(userData.password, saltRounds);

      // Create user in database
      const [user] = await db
        .insert(users)
        .values({
          email: userData.email,
          username: userData.username,
          passwordHash,
          firstName: userData.firstName,
          lastName: userData.lastName,
          authProvider: "local",
          isEmailVerified: false,
          subscriptionStatus: "free_trial",
          subscriptionExpiresAt: new Date(Date.now() + (7 * 24 * 60 * 60 * 1000)), // 7 days from now
        })
        .returning();

      return user;
    } catch (error) {
      throw error;
    }
  }

  async getUserByUsernameOrEmail(identifier: string): Promise<User | undefined> {
    const [user] = await db
      .select()
      .from(users)
      .where(or(eq(users.username, identifier), eq(users.email, identifier)));
    return user;
  }

  async getUserByEmail(email: string): Promise<User | undefined> {
    const [user] = await db
      .select()
      .from(users)
      .where(eq(users.email, email));
    return user;
  }

  async getUsersByAppleTransactionId(transactionId: string): Promise<User[]> {
    const usersResult = await db
      .select()
      .from(users)
      .where(eq(users.appleOriginalTransactionId, transactionId));
    return usersResult;
  }

  async getUser(id: string): Promise<User | undefined> {
    const [user] = await db
      .select()
      .from(users)
      .where(eq(users.id, id));
    return user;
  }

  async upsertUser(userData: UpsertUser): Promise<User> {
    const [user] = await db
      .insert(users)
      .values(userData)
      .onConflictDoUpdate({
        target: users.id,
        set: {
          ...userData,
          updatedAt: new Date(),
        },
      })
      .returning();
    return user;
  }


