@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer utilities {
  /*
   Safe Area Utilities
   - Use `.pt-safe` and `.pb-safe` on primary containers to avoid notches, status bars, and home indicators
   - Apply `.safe-area-inset-top` / `.safe-area-inset-bottom` to fixed headers/footers when needed
   - These rely on CSS env() variables and gracefully fallback on Android/web (0px)
  */
  .bg-gradient-radial {
    background-image: radial-gradient(var(--tw-gradient-stops));
  }

  .hexagon-bg {
    background-image: 
      radial-gradient(circle at 50% 50%, rgba(220, 38, 38, 0.1) 0%, transparent 50%),
      radial-gradient(circle at 25% 25%, rgba(0, 0, 0, 0.8) 0%, transparent 50%),
      radial-gradient(circle at 75% 75%, rgba(220, 38, 38, 0.15) 0%, transparent 50%);
    background-size: 120px 104px, 80px 69px, 100px 87px;
    background-position: 0 0, 60px 52px, 30px 26px;
    animation: hexagon-float 20s ease-in-out infinite;
  }

  .hexagon-pattern {
    background-image: url("data:image/svg+xml,%3Csvg width='120' height='104' viewBox='0 0 120 104' xmlns='http://www.w3.org/2000/svg'%3E%3Cpolygon points='30,2 90,2 120,52 90,102 30,102 0,52' fill='none' stroke='%23dc2626' stroke-width='1' opacity='0.1'/%3E%3C/svg%3E");
    background-size: 120px 104px;
    background-repeat: repeat;
  }

  @keyframes hexagon-float {
    0%, 100% { transform: translateY(0px) rotate(0deg); }
    33% { transform: translateY(-10px) rotate(1deg); }
    66% { transform: translateY(5px) rotate(-1deg); }
  }

  /* Mobile-specific animations (playful, energetic) */
  @keyframes mobile-slide-up {
    0% { 
      opacity: 0; 
      transform: translateY(30px); 
    }
    100% { 
      opacity: 1; 
      transform: translateY(0); 
    }
  }

  @keyframes mobile-bounce-in {
    0% { 
      opacity: 0; 
      transform: scale(0.8) translateY(20px); 
    }
    50% { 
      transform: scale(1.05) translateY(-5px); 
    }
    100% { 
      opacity: 1; 
      transform: scale(1) translateY(0); 
    }
  }

  @keyframes mobile-pop {
    0% { transform: scale(1); }
    50% { transform: scale(1.15); }
    100% { transform: scale(1); }
  }

  @keyframes mobile-pulse {
    0%, 100% { 
      transform: scale(1);
      opacity: 1;
    }
    50% { 
      transform: scale(1.05);
      opacity: 0.9;
    }
  }

  /* Desktop-specific animations (smooth, professional) */
  @keyframes desktop-fade-in {
    0% { 
      opacity: 0; 
    }
    100% { 
      opacity: 1; 
    }
  }

  @keyframes desktop-scale-in {
    0% { 
      opacity: 0; 
      transform: scale(0.95); 
    }
    100% { 
      opacity: 1; 
      transform: scale(1); 
    }
  }

  @keyframes desktop-slide-from-left {
    0% { 
      opacity: 0; 
      transform: translateX(-20px); 
    }
    100% { 
      opacity: 1; 
      transform: translateX(0); 
    }
  }

  @keyframes desktop-glow {
    0%, 100% { 
      box-shadow: 0 0 5px rgba(220, 38, 38, 0.3);
    }
    50% { 
      box-shadow: 0 0 20px rgba(220, 38, 38, 0.5);
    }
  }

  /* Mobile animation classes */
  .mobile-slide-up {
    animation: mobile-slide-up 0.4s ease-out forwards;
  }

  .mobile-bounce-in {
    animation: mobile-bounce-in 0.5s cubic-bezier(0.68, -0.55, 0.265, 1.55) forwards;
  }

  .mobile-pop {
    animation: mobile-pop 0.3s ease-in-out;
  }

  .mobile-pulse {
    animation: mobile-pulse 2s ease-in-out infinite;
  }

  /* Desktop animation classes */
  .desktop-fade-in {
    animation: desktop-fade-in 0.3s ease-out forwards;
  }

  .desktop-scale-in {
    animation: desktop-scale-in 0.4s ease-out forwards;
  }

  .desktop-slide-from-left {
    animation: desktop-slide-from-left 0.3s ease-out forwards;
  }

  .desktop-glow {
    animation: desktop-glow 2s ease-in-out infinite;
  }

  /* Mobile app utilities */
  .pt-safe {
    padding-top: env(safe-area-inset-top, 0px);
  }
  .pl-safe {
    padding-left: env(safe-area-inset-left, 0px);
  }
  .pr-safe {
    padding-right: env(safe-area-inset-right, 0px);
  }
  .pb-safe {
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }

  .safe-area-inset-top {
    padding-top: env(safe-area-inset-top, 0px);
  }
  .safe-area-inset-bottom {
    padding-bottom: env(safe-area-inset-bottom, 0px);
  }

  /* Mobile-native large titles */
  .mobile-large-title {
    font-size: 2rem;
    font-weight: 700;
    line-height: 1.2;
    letter-spacing: -0.02em;
  }

  .mobile-subtitle {
    font-size: 0.9rem;
    font-weight: 400;
    opacity: 0.7;
    line-height: 1.4;
  }

  /* Floating Action Button */
  .fab {
    @apply fixed bottom-20 right-4 md:bottom-6 md:right-6 w-14 h-14 rounded-full shadow-2xl flex items-center justify-center z-40;
    @apply bg-gradient-to-br from-primary to-orange-600 text-white;
    @apply transition-all duration-300 hover:scale-110 active:scale-95;
  }

  /* Touch ripple effect */
  @keyframes ripple {
    0% {
      transform: scale(0);
      opacity: 0.6;
    }
    100% {
      transform: scale(2.5);
      opacity: 0;
    }
  }

  .touch-ripple {
    position: relative;
    overflow: hidden;
  }

  .touch-ripple::after {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    width: 100%;
    height: 100%;
    background: rgba(255, 255, 255, 0.3);
    border-radius: 50%;
    transform: translate(-50%, -50%) scale(0);
    pointer-events: none;
  }

  .touch-ripple:active::after {
    animation: ripple 0.6s ease-out;
  }

  /* Pull to refresh loader */
  @keyframes pull-refresh-spin {
    to { transform: rotate(360deg); }
  }

  .pull-refresh-spinner {
    animation: pull-refresh-spin 1s linear infinite;
  }

  /* Mobile card with better touch affordances */
  .mobile-card {
    @apply rounded-2xl p-4 shadow-lg;
    @apply transition-all duration-200 active:scale-[0.98];
    min-height: 44px; /* iOS minimum touch target */
  }

  /* Backdrop blur for native feel */
  .mobile-header-blur {
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    background: rgba(255, 255, 255, 0.8);
  }

  .dark .mobile-header-blur {
    background: rgba(0, 0, 0, 0.8);
  }

  /* 8pt grid spacing system */
  .spacing-xs { margin: 8px; }
  .spacing-sm { margin: 16px; }
  .spacing-md { margin: 24px; }
  .spacing-lg { margin: 32px; }
  .spacing-xl { margin: 40px; }

  /* Swipeable item indicator */
  .swipe-indicator {
    @apply absolute right-0 top-0 bottom-0 w-20;
    @apply bg-gradient-to-l from-red-500 to-transparent;
    @apply flex items-center justify-end pr-4;
    transform: translateX(100%);
    transition: transform 0.3s ease;
  }

  .swipe-item:hover .swipe-indicator {
    transform: translateX(0);
  }
}

