import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { TrendingUp, TrendingDown, Minus, Target, Zap, Award, BarChart3, Brain } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { apiRequest } from "@/lib/queryClient";

interface WorkoutPerformanceData {
  workouts: Array<{
    id: string;
    name: string;
    date: string;
    difficultyLevel: number;
    perceivedExertion: number;
    completionRate: number;
    performanceScore: number;
    category: string;
  }>;
  trends: {
    difficultyTrend: "improving" | "declining" | "stable";
    consistencyScore: number;
    averageDifficulty: number;
    averageExertion: number;
    completionRate: number;
  };
}

export default function PerformanceAnalytics() {
  const [selectedTimeframe, setSelectedTimeframe] = useState("7d");

  const { data: performanceData, isLoading } = useQuery<WorkoutPerformanceData>({
    queryKey: ["/api/performance-analytics", selectedTimeframe],
    enabled: true,
  });

  const getTrendIcon = (trend: string) => {
    switch (trend) {
      case "improving":
        return <TrendingUp className="w-5 h-5 text-green-500" />;
      case "declining":
        return <TrendingDown className="w-5 h-5 text-red-500" />;
      default:
        return <Minus className="w-5 h-5 text-yellow-500" />;
    }
  };

  const getTrendColor = (trend: string) => {
    switch (trend) {
      case "improving":
        return "text-green-600 bg-green-50 border-green-200";
      case "declining":
        return "text-red-600 bg-red-50 border-red-200";
      default:
        return "text-yellow-600 bg-yellow-50 border-yellow-200";
    }
  };

  const getConsistencyColor = (score: number) => {
    if (score >= 80) return "text-green-600";
    if (score >= 60) return "text-yellow-600";
    return "text-red-600";
  };

  if (isLoading) {
    return (
      <section className="relative bg-gradient-to-br from-black via-red-900/30 to-black rounded-3xl shadow-2xl border border-red-600/50 p-8 overflow-hidden hexagon-bg">
        <div className="flex items-center justify-center h-64">
          <div className="animate-spin w-8 h-8 border-4 border-red-600 border-t-transparent rounded-full"></div>
        </div>
      </section>
    );
  }

  return (
    <section className="relative bg-gradient-to-br from-black via-red-900/30 to-black rounded-3xl shadow-2xl border border-red-600/50 p-8 overflow-hidden hexagon-bg hexagon-pattern">
      {/* Animated Background Elements */}
      <div className="absolute inset-0">
        <div className="absolute top-0 right-0 w-32 h-28 opacity-25 animate-pulse" style={{animationDuration: '6s'}}>
          <svg viewBox="0 0 120 104" className="w-full h-full">
            <polygon points="30,2 90,2 120,52 90,102 30,102 0,52" fill="#dc2626" stroke="#dc2626" strokeWidth="2" opacity="0.5"/>
          </svg>
        </div>
        <div className="absolute bottom-1/4 left-0 w-24 h-21 opacity-20 animate-bounce" style={{animationDuration: '8s'}}>
          <svg viewBox="0 0 120 104" className="w-full h-full">
            <polygon points="30,2 90,2 120,52 90,102 30,102 0,52" fill="none" stroke="#dc2626" strokeWidth="2" opacity="0.7"/>
          </svg>
        </div>
      </div>

      {/* Header */}
      <div className="relative z-10 mb-8">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-3xl font-bold text-white flex items-center gap-3">
              <Brain className="w-8 h-8 text-red-400" />
              AI Performance Analytics
            </h2>
            <p className="text-red-200/80 mt-2">Track your progress with intelligent insights</p>
          </div>

          {/* Timeframe Selector */}
          <div className="w-40">
            <Select value={selectedTimeframe} onValueChange={setSelectedTimeframe}>
              <SelectTrigger 
                className="bg-black/50 border-red-600/30 text-white focus:ring-red-600 focus:border-red-600"
                data-testid="timeframe-selector"
              >
                <SelectValue placeholder="Select timeframe" />
              </SelectTrigger>
              <SelectContent className="bg-black/90 border-red-600/30">
                <SelectItem 
                  value="7d" 
                  className="text-white hover:bg-red-600/20 focus:bg-red-600/30"
                  data-testid="timeframe-7d"
                >
                  7 Days
                </SelectItem>
                <SelectItem 
                  value="30d" 
                  className="text-white hover:bg-red-600/20 focus:bg-red-600/30"
                  data-testid="timeframe-30d"
                >
                  30 Days
                </SelectItem>
                <SelectItem 
                  value="90d" 
                  className="text-white hover:bg-red-600/20 focus:bg-red-600/30"
                  data-testid="timeframe-90d"
                >
                  3 Months
                </SelectItem>
              </SelectContent>
            </Select>
          </div>
        </div>
      </div>

      {/* Performance Metrics Grid */}
      <div className="relative z-10 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        {/* Performance Trend */}
        <div className="bg-white/10 backdrop-blur-sm rounded-2xl p-6 border border-red-600/30">
          <div className="flex items-center gap-3 mb-3">
            {getTrendIcon(performanceData?.trends.difficultyTrend || "stable")}
            <h3 className="font-semibold text-white">Performance Trend</h3>
          </div>
          <div className={`inline-flex items-center px-3 py-1 rounded-full text-sm font-medium border ${getTrendColor(performanceData?.trends.difficultyTrend || "stable")}`}>
            {performanceData?.trends.difficultyTrend ? 
              performanceData.trends.difficultyTrend.charAt(0).toUpperCase() + performanceData.trends.difficultyTrend.slice(1) : 
              "Stable"
            }
          </div>
        </div>

        {/* Consistency Score */}
        <div className="bg-white/10 backdrop-blur-sm rounded-2xl p-6 border border-red-600/30">
          <div className="flex items-center gap-3 mb-3">
            <Target className="w-5 h-5 text-blue-400" />
            <h3 className="font-semibold text-white">Consistency</h3>
          </div>
          <div className="text-2xl font-bold text-white mb-1">
            {performanceData?.trends.consistencyScore || 0}%
          </div>
          <div className={`text-sm font-medium ${getConsistencyColor(performanceData?.trends.consistencyScore || 0)}`}>
            {(performanceData?.trends.consistencyScore || 0) >= 80 ? "Excellent" : 
             (performanceData?.trends.consistencyScore || 0) >= 60 ? "Good" : "Needs Improvement"}
          </div>
        </div>

        {/* Average Difficulty */}
        <div className="bg-white/10 backdrop-blur-sm rounded-2xl p-6 border border-red-600/30">
          <div className="flex items-center gap-3 mb-3">
            <Zap className="w-5 h-5 text-yellow-400" />
            <h3 className="font-semibold text-white">Avg Difficulty</h3>
          </div>
          <div className="text-2xl font-bold text-white mb-1">
            {performanceData?.trends.averageDifficulty?.toFixed(1) || "0.0"}/5.0
          </div>
          <div className="text-sm text-red-200/70">
            {(performanceData?.trends.averageDifficulty || 0) >= 4 ? "High Intensity" : 
             (performanceData?.trends.averageDifficulty || 0) >= 3 ? "Moderate" : "Light Training"}
          </div>
        </div>

        {/* Completion Rate */}
        <div className="bg-white/10 backdrop-blur-sm rounded-2xl p-6 border border-red-600/30">
          <div className="flex items-center gap-3 mb-3">
            <Award className="w-5 h-5 text-green-400" />
            <h3 className="font-semibold text-white">Completion Rate</h3>
          </div>
          <div className="text-2xl font-bold text-white mb-1">
            {performanceData?.trends.completionRate || 0}%
          </div>
          <div className="text-sm text-red-200/70">
            Workouts finished
          </div>
        </div>
      </div>

      {/* Recent Workouts Performance */}
      <div className="relative z-10">
        <h3 className="text-xl font-bold text-white mb-6 flex items-center gap-2">
          <BarChart3 className="w-6 h-6 text-red-400" />
          Recent Performance History
        </h3>

        <div className="space-y-4 max-h-80 overflow-y-auto">
          {performanceData?.workouts && performanceData.workouts.length > 0 ? (
            performanceData.workouts.map((workout) => (
              <div key={workout.id} className="bg-white/10 backdrop-blur-sm rounded-xl p-4 border border-red-600/20">
                <div className="flex items-center justify-between">
                  <div>
                    <h4 className="font-medium text-white">{workout.name}</h4>
                    <p className="text-sm text-red-200/70">{workout.category} • {new Date(workout.date).toLocaleDateString()}</p>
                  </div>
                  <div className="flex gap-4 text-sm">
                    <div className="text-center">
                      <div className="text-yellow-400 font-semibold">{workout.difficultyLevel}/5</div>
                      <div className="text-red-200/60">Difficulty</div>
                    </div>
                    <div className="text-center">
                      <div className="text-blue-400 font-semibold">{workout.perceivedExertion}/10</div>
                      <div className="text-red-200/60">RPE</div>
                    </div>
                    <div className="text-center">
                      <div className="text-green-400 font-semibold">{workout.completionRate}%</div>
                      <div className="text-red-200/60">Complete</div>
                    </div>
                    {workout.performanceScore && (
                      <div className="text-center">
                        <div className="text-purple-400 font-semibold">{workout.performanceScore}</div>
                        <div className="text-red-200/60">AI Score</div>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div className="text-center py-8">
              <div className="text-red-200/60 mb-4">
                <BarChart3 className="w-12 h-12 mx-auto opacity-50" />
              </div>
              <p className="text-red-200/80">No performance data yet</p>
              <p className="text-sm text-red-200/60">Complete workouts to see your analytics</p>
            </div>
          )}
        </div>
      </div>

      {/* AI Insights */}
      <div className="relative z-10 mt-8 p-6 bg-gradient-to-r from-purple-900/30 to-blue-900/30 rounded-2xl border border-purple-600/30">
        <h3 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
          🧠 AI Performance Insights
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
          <div className="text-purple-200">
            <strong>Trend Analysis:</strong> {performanceData?.trends.difficultyTrend === "improving" ? 
              "You're progressively challenging yourself - great job!" :
              performanceData?.trends.difficultyTrend === "declining" ?
              "Consider gradually increasing workout intensity." :
              "Your performance is stable. Try varying difficulty levels."
            }
          </div>
          <div className="text-blue-200">
            <strong>Recommendation:</strong> {(performanceData?.trends.consistencyScore || 0) < 60 ?
              "Focus on consistency - aim for regular workout schedule." :
              "Excellent consistency! Consider progressive overload for continued growth."
            }
          </div>
        </div>
      </div>
    </section>
  );
}

server/services/content-moderation.ts.content:
import OpenAI from "openai";

// This is using OpenAI's API, which points to OpenAI's API servers and requires your own API key.
const openai = new OpenAI({ 
  apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY || process.env.OPENAI_API_KEY,
  baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL
});

interface ModerationResult {
  isAppropriate: boolean;
  reason?: string;
  categories?: string[];
}

/**
 * Moderates text content for inappropriate language
 */
export async function moderateText(text: string): Promise<ModerationResult> {
  try {
    // Use OpenAI's moderation endpoint
    const moderation = await openai.moderations.create({
      input: text,
    });

    const result = moderation.results[0];

    // Check if content is flagged
    if (result.flagged) {
      const flaggedCategories = Object.keys(result.categories).filter(
        key => result.categories[key as keyof typeof result.categories]
      );

      return {
        isAppropriate: false,
        reason: "Content contains inappropriate language or themes",
        categories: flaggedCategories
      };
    }

    return { isAppropriate: true };
  } catch (error) {
    console.error("Error moderating text:", error);
    // In case of error, allow content but log the error
    return { isAppropriate: true };
  }
}

/**
 * Moderates image content for inappropriate visuals
 */
export async function moderateImage(imageUrl: string): Promise<ModerationResult> {
  try {
    // the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
    const response = await openai.chat.completions.create({
      model: "gpt-5",
      messages: [
        {
          role: "system",
          content: "You are a content moderation expert. Analyze the image and determine if it contains any inappropriate, explicit, violent, or offensive content. Respond with JSON in this format: { 'isAppropriate': boolean, 'reason': string, 'categories': string[] }"
        },
        {
          role: "user",
          content: [
            {
              type: "text",
              text: "Is this image appropriate for a fitness community platform? Check for nudity, violence, hate symbols, or other inappropriate content."
            },
            {
              type: "image_url",
              image_url: { url: imageUrl }
            }
          ]
        }
      ],
      response_format: { type: "json_object" },
      max_completion_tokens: 500
    });

    const result = JSON.parse(response.choices[0].message.content || '{"isAppropriate": true}');

    return {
      isAppropriate: result.isAppropriate,
      reason: result.reason,
      categories: result.categories || []
    };
  } catch (error) {
    console.error("Error moderating image:", error);
    // In case of error, allow content but log the error
    return { isAppropriate: true };
  }
}

server/services/ai-workout-generator.ts.content:
import OpenAI from "openai";

// the newest OpenAI model is "gpt-5" which was released August 7, 2025. do not change this unless explicitly requested by the user
const openai = new OpenAI({ 
  apiKey: process.env.AI_INTEGRATIONS_OPENAI_API_KEY || process.env.OPENAI_API_KEY,
  baseURL: process.env.AI_INTEGRATIONS_OPENAI_BASE_URL
});

interface WorkoutPreferences {
  fitnessLevel: string;
  primaryGoals: string[];
  workoutDaysPerWeek: number;
  sessionDuration: number;
  availableEquipment: string[];
  preferredWorkoutTypes: string[];
  injuriesOrLimitations: string[];
}

interface Exercise {
  name: string;
  sets: number;
  reps: string;
  restSeconds: number;
  notes: string;
}

interface DailyWorkout {
  dayOfWeek: number;
  weekNumber: number;
  workoutType: string;
  name: string;
  description: string;
  exercises: Exercise[];
  estimatedDuration: number;
  targetCalories: number;
  isRestDay: boolean;
}

export class AIWorkoutGenerator {
  async generatePersonalizedPlan(preferences: WorkoutPreferences): Promise<DailyWorkout[]> {
    try {
      const prompt = this.buildWorkoutPrompt(preferences);

      const response = await openai.chat.completions.create({
        model: "gpt-5",
        messages: [
          {
            role: "system",
            content: "You are an expert personal trainer and exercise physiologist. Create safe, effective, and personalized workout plans based on user preferences, goals, and limitations. Always provide specific exercises with sets, reps, and proper form cues."
          },
          {
            role: "user",
            content: prompt
          }
        ],
        response_format: { type: "json_object" }
      });

      const aiPlan = JSON.parse(response.choices[0].message.content || '{}');
      return this.formatWorkoutPlan(aiPlan, preferences);
    } catch (error) {
      console.error("Error generating AI workout plan:", error);
      throw new Error("Failed to generate personalized workout plan");
    }
  }

  private buildWorkoutPrompt(preferences: WorkoutPreferences): string {
    const equipmentList = preferences.availableEquipment.join(', ') || 'bodyweight only';
    const goalsList = preferences.primaryGoals.join(', ');
    const limitations = preferences.injuriesOrLimitations.filter(l => l !== 'none').join(', ') || 'none';
    const workoutTypes = preferences.preferredWorkoutTypes.join(', ') || 'any';

    return `Create a personalized 4-week workout plan with the following requirements:

**User Profile:**
- Fitness Level: ${preferences.fitnessLevel}
- Primary Goals: ${goalsList}
- Workout Days Per Week: ${preferences.workoutDaysPerWeek}
- Session Duration: ${preferences.sessionDuration} minutes
- Available Equipment: ${equipmentList}
- Preferred Workout Types: ${workoutTypes}
- Injuries/Limitations: ${limitations}

**Requirements:**
1. Generate exactly ${preferences.workoutDaysPerWeek} workout days per week (distribute them properly throughout the week)
2. Each workout should fit within ${preferences.sessionDuration} minutes
3. Include specific exercises with sets, reps/duration, and rest periods
4. Consider the user's limitations and avoid exercises that may cause injury
5. Progressive overload - gradually increase difficulty over the 4 weeks
6. Balance muscle groups and workout types based on goals
7. Include rest days on non-workout days

**Output Format (JSON):**
{
  "plan": {
    "weeks": [
      {
        "weekNumber": 1,
        "workouts": [
          {
            "dayOfWeek": 1,  // 0=Sunday, 1=Monday, etc.
            "isRestDay": false,
            "workoutType": "strength|cardio|yoga|functional",
            "name": "Workout Name",
            "description": "Brief workout description",
            "estimatedDuration": ${preferences.sessionDuration},
            "targetCalories": 300,
            "exercises": [
              {
                "name": "Exercise name",
                "sets": 3,
                "reps": "12" or "30 seconds" for timed exercises,
                "restSeconds": 60,
                "notes": "Form cues and tips"
              }
            ]
          }
        ]
      }
    ]
  }
}

Focus on exercises that:
- Match available equipment: ${equipmentList}
- Are safe for limitations: ${limitations}
- Align with goals: ${goalsList}
- Suit fitness level: ${preferences.fitnessLevel}

Make the plan progressive, balanced, and achievable!`;
  }

  private formatWorkoutPlan(aiPlan: any, preferences: WorkoutPreferences): DailyWorkout[] {
    const formattedWorkouts: DailyWorkout[] = [];

    if (!aiPlan.plan?.weeks) {
      throw new Error("Invalid AI response format");
    }

    // Process all 4 weeks
    aiPlan.plan.weeks.forEach((week: any) => {
      const weekNumber = week.weekNumber;

      // Create a full week array (7 days)
      const weekDays = Array(7).fill(null).map((_, dayIndex) => {
        // Find if there's a workout for this day
        const workout = week.workouts?.find((w: any) => w.dayOfWeek === dayIndex);

        if (workout && !workout.isRestDay) {
          return {
            dayOfWeek: dayIndex,
            weekNumber,
            workoutType: workout.workoutType,
            name: workout.name,
            description: workout.description,
            exercises: workout.exercises || [],
            estimatedDuration: workout.estimatedDuration || preferences.sessionDuration,
            targetCalories: workout.targetCalories || this.estimateCalories(workout.estimatedDuration, workout.workoutType),
            isRestDay: false
          };
        } else {
          // Rest day
          return {
            dayOfWeek: dayIndex,
            weekNumber,
            workoutType: 'rest',
            name: 'Rest Day',
            description: 'Recovery day - light stretching or walking optional',
            exercises: [],
            estimatedDuration: 0,
            targetCalories: 0,
            isRestDay: true
          };
        }
      });

      formattedWorkouts.push(...weekDays);
    });

    return formattedWorkouts;
  }

  private estimateCalories(duration: number, workoutType: string): number {
    const caloriesPerMinute: { [key: string]: number } = {
      strength: 5,
      cardio: 8,
      yoga: 3,
      functional: 6,
      rest: 0
    };

    const rate = caloriesPerMinute[workoutType] || 5;
    return Math.round(duration * rate);
  }
}

export const aiWorkoutGenerator = new AIWorkoutGenerator();

