  const mainNavItems = [
    { path: "/", label: "Home", icon: Home },
    { path: "/workouts", label: "Workouts", icon: Dumbbell },
    { path: "/progress", label: "Progress", icon: TrendingUp },
    { path: "/community", label: "Community", icon: Users },
