    { path: "/news", label: "What's New", icon: Newspaper },
    { path: "/meal-plans", label: "Meal Plans", icon: ChefHat },
    { path: "/workout-planner", label: "Workout Planner", icon: Target },
    { path: "/meal-tracker", label: "Barcode Scanner", icon: Apple },
