                  className={`transition-all duration-300 ${
                    active 
                      ? "text-primary mobile-pulse" 
                      : "text-gray-500 dark:text-gray-400"
                  }`}
                  strokeWidth={active ? 2.5 : 2}
                  aria-hidden="true"
                />
                <span 
