import { useEffect } from 'react';
import { Mic, MicOff } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { useVoiceInput } from '@/hooks/useVoiceInput';
import { useToast } from '@/hooks/use-toast';
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip';

interface VoiceSearchButtonProps {
  onTranscript: (text: string) => void;
  className?: string;
}

export default function VoiceSearchButton({ onTranscript, className }: VoiceSearchButtonProps) {
  const { isListening, transcript, isSupported, startListening, stopListening } = useVoiceInput();
  const { toast } = useToast();

  // Update the search query when transcript changes
  useEffect(() => {
    if (transcript) {
      onTranscript(transcript);
    }
  }, [transcript, onTranscript]);

  const handleClick = () => {
    if (!isSupported) {
      toast({
        title: "Not Supported",
        description: "Voice search is not supported in your browser. Try Chrome, Edge, or Safari.",
        variant: "destructive",
      });
      return;
    }

    if (isListening) {
      stopListening();
    } else {
      startListening();
      toast({
        title: "Listening...",
        description: "Speak now to search",
      });
    }
  };

  if (!isSupported) {
    return null; // Don't show button if not supported
  }

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <Button
          type="button"
          variant={isListening ? "default" : "ghost"}
          size="icon"
          onClick={handleClick}
          className={className}
          data-testid={isListening ? "button-stop-voice" : "button-start-voice"}
        >
          {isListening ? (
            <MicOff className="h-4 w-4 animate-pulse" />
          ) : (
            <Mic className="h-4 w-4" />
          )}
        </Button>
      </TooltipTrigger>
      <TooltipContent>
        <p>{isListening ? "Stop listening" : "Voice search"}</p>
      </TooltipContent>
    </Tooltip>
  );
}

client/src/hooks/useVoiceInput.ts.content:
import { useState, useCallback, useRef, useEffect } from 'react';

interface SpeechRecognitionEvent extends Event {
  results: {
    [index: number]: {
      [index: number]: {
        transcript: string;
      };
      isFinal: boolean;
    };
    length: number;
  };
}

interface SpeechRecognitionErrorEvent extends Event {
  error: string;
}

interface SpeechRecognition extends EventTarget {
  continuous: boolean;
  interimResults: boolean;
  lang: string;
  start: () => void;
  stop: () => void;
  abort: () => void;
  onresult: ((event: SpeechRecognitionEvent) => void) | null;
  onerror: ((event: SpeechRecognitionErrorEvent) => void) | null;
  onend: (() => void) | null;
  onstart: (() => void) | null;
}

declare global {
  interface Window {
    SpeechRecognition: new () => SpeechRecognition;
    webkitSpeechRecognition: new () => SpeechRecognition;
  }
}

export function useVoiceInput() {
  const [isListening, setIsListening] = useState(false);
  const [transcript, setTranscript] = useState('');
  const [isSupported, setIsSupported] = useState(false);
  const recognitionRef = useRef<SpeechRecognition | null>(null);

  useEffect(() => {
    // Check if browser supports Speech Recognition
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    setIsSupported(!!SpeechRecognition);

    if (SpeechRecognition) {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = false;
      recognition.lang = 'en-US';

      recognition.onresult = (event: SpeechRecognitionEvent) => {
        const current = event.results[event.results.length - 1];
        const transcript = current[0].transcript;
        setTranscript(transcript);
      };

      recognition.onerror = (event: SpeechRecognitionErrorEvent) => {
        console.error('Speech recognition error:', event.error);
        setIsListening(false);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognition.onstart = () => {
        setIsListening(true);
      };

      recognitionRef.current = recognition;
    }

    return () => {
      if (recognitionRef.current) {
        recognitionRef.current.abort();
      }
    };
  }, []);

  const startListening = useCallback(() => {
    if (recognitionRef.current && !isListening) {
      setTranscript('');
      try {
        recognitionRef.current.start();
      } catch (error) {
        console.error('Error starting speech recognition:', error);
      }
    }
  }, [isListening]);

  const stopListening = useCallback(() => {
    if (recognitionRef.current && isListening) {
      recognitionRef.current.stop();
    }
  }, [isListening]);

  const resetTranscript = useCallback(() => {
    setTranscript('');
  }, []);

  return {
    isListening,
    transcript,
    isSupported,
    startListening,
    stopListening,
    resetTranscript,
  };
}

server/badge-service.ts.content:
import { storage } from "./storage";
import type { Badge, UserBadge, InsertBadge } from "@shared/schema";

export interface BadgeAward {
  badgeId: string;
  badgeName: string;
  description: string;
  isNew: boolean;
}

export class BadgeService {
  // Consistency badges definition
  private static readonly CONSISTENCY_BADGES: InsertBadge[] = [
    {
      name: "Week Warrior",
      description: "Used the app every day for 1 week",
      iconName: "flame",
      category: "consistency",
      requiredDays: 7,
    },
    {
      name: "Fortnight Champion",
      description: "Used the app every day for 2 weeks",
      iconName: "zap",
      category: "consistency",
      requiredDays: 14,
    },
    {
      name: "Monthly Master",
      description: "Used the app every day for 1 month",
      iconName: "trophy",
      category: "consistency",
      requiredDays: 30,
    },
  ];

  /**
   * Initialize default badges in the database
   * Should be called once during app setup
   */
  static async initializeBadges(): Promise<void> {
    try {
      for (const badgeData of this.CONSISTENCY_BADGES) {
        await storage.createBadgeIfNotExists(badgeData);
      }
    } catch (error) {
      console.error("Failed to initialize badges:", error);
    }
  }

  /**
   * Check and award badges to a user based on their current streak
   * Returns array of newly earned badges
   */
  static async checkAndAwardBadges(userId: string): Promise<BadgeAward[]> {
    try {
      const awardedBadges: BadgeAward[] = [];

      // Get user's current streak
      const user = await storage.getUser(userId);
      if (!user) {
        return [];
      }

      const currentStreak = user.streak || 0;

      // Get all consistency badges
      const allBadges = await storage.getAllBadges();
      const consistencyBadges = allBadges.filter(b => b.category === "consistency");

      // Get user's existing badges
      const userBadges = await storage.getUserBadges(userId);
      const earnedBadgeIds = new Set(userBadges.map(ub => ub.badgeId));

      // Check each consistency badge
      for (const badge of consistencyBadges) {
        // Skip if user already has this badge
        if (earnedBadgeIds.has(badge.id)) {
          continue;
        }

        // Check if user's streak qualifies for this badge
        if (badge.requiredDays && currentStreak >= badge.requiredDays) {
          // Award the badge
          await storage.awardBadge(userId, badge.id);

          awardedBadges.push({
            badgeId: badge.id,
            badgeName: badge.name,
            description: badge.description,
            isNew: true,
          });
        }
      }

      return awardedBadges;
    } catch (error) {
      console.error("Failed to check and award badges:", error);
      return [];
    }
  }

  /**
   * Get all badges earned by a user
   */
  static async getUserBadges(userId: string): Promise<UserBadge[]> {
    try {
      return await storage.getUserBadges(userId);
    } catch (error) {
      console.error("Failed to get user badges:", error);
      return [];
    }
  }

  /**
   * Get all available badges
   */
  static async getAllBadges(): Promise<Badge[]> {
    try {
      return await storage.getAllBadges();
    } catch (error) {
      console.error("Failed to get all badges:", error);
      return [];
    }
  }
}

// Export singleton instance
export const badgeService = BadgeService;

